/**
 * Synthetic demo shop. Everything is invented, but it is generated by a small
 * simulation (customers, weekday patterns, deliveries, stock limits) and then
 * recorded through the same preview → confirm path as real entries, so every
 * number the analyst reports can be checked against receipts.
 *
 * Planted story for the demo ("why were sales down on Tuesday?"):
 *  - On the most recent completed Tuesday, Ramesh (a tea-stall owner who buys
 *    every Tuesday and Friday) doesn't come.
 *  - The sugar delivery was short that week, so sugar runs out late in the morning.
 * Other stories: Farooq's credit keeps growing with no payment for ~4 weeks
 * (credit risk); Ghee and Hair Oil haven't sold in weeks (dead stock); sugar,
 * milk and a few others are close to running out today (low stock).
 */
import type { Ledger } from "../../../packages/domain/src/ledger";

const TZ_OFFSET = "+05:30";
const HISTORY_DAYS = 35;

type Product = {
  name: string;
  unit: "kg" | "packet" | "piece";
  stock: number;
  price: number;
  cost: number;
  pack: number;
  leadDays: number;
  aliases?: string[];
};
// prices in paise, quantities in thousandths of a unit
export const DEMO_PRODUCTS: Product[] = [
  { name: "Sugar", unit: "kg", stock: 14000, price: 4800, cost: 4200, pack: 5000, leadDays: 1 },
  { name: "Rice", unit: "kg", stock: 40000, price: 6000, cost: 4800, pack: 5000, leadDays: 2 },
  { name: "Atta", unit: "kg", stock: 40000, price: 4500, cost: 3800, pack: 10000, leadDays: 1 },
  { name: "Toor Dal", unit: "kg", stock: 15000, price: 14000, cost: 11800, pack: 5000, leadDays: 2 },
  { name: "Mustard Oil", unit: "piece", stock: 18000, price: 18000, cost: 15500, pack: 6000, leadDays: 3, aliases: ["oil bottle"] },
  { name: "Tea", unit: "packet", stock: 20000, price: 13000, cost: 10500, pack: 10000, leadDays: 2 },
  { name: "Milk", unit: "packet", stock: 30000, price: 3000, cost: 2700, pack: 10000, leadDays: 1 },
  { name: "Biscuits", unit: "packet", stock: 60000, price: 1000, cost: 800, pack: 24000, leadDays: 1, aliases: ["parle g"] },
  { name: "Salt", unit: "packet", stock: 20000, price: 2800, cost: 2200, pack: 10000, leadDays: 2 },
  { name: "Eggs", unit: "piece", stock: 60000, price: 700, cost: 550, pack: 30000, leadDays: 1 },
  { name: "Soap", unit: "piece", stock: 24000, price: 4000, cost: 3200, pack: 12000, leadDays: 2 },
  { name: "Noodles", unit: "packet", stock: 48000, price: 1400, cost: 1200, pack: 24000, leadDays: 1 },
  { name: "Ghee", unit: "piece", stock: 7000, price: 65000, cost: 58000, pack: 6000, leadDays: 3 },
  { name: "Hair Oil", unit: "piece", stock: 10000, price: 12000, cost: 9500, pack: 6000, leadDays: 3 },
];
export const DEMO_CUSTOMERS = ["Ramesh", "Meena", "Suresh", "Anita", "Farooq", "Lakshmi"];

/** Small deterministic PRNG so the demo is reproducible. */
function rng(seed: number) {
  return () => {
    seed |= 0;
    seed = (seed + 0x6d2b79f5) | 0;
    let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const istDay = (ms: number) =>
  new Intl.DateTimeFormat("en-CA", {
    timeZone: "Asia/Kolkata",
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
  }).format(new Date(ms));
const addDays = (key: string, n: number) => {
  const d = new Date(key + "T12:00:00Z");
  d.setUTCDate(d.getUTCDate() + n);
  return d.toISOString().slice(0, 10);
};
const weekday = (key: string) => new Date(key + "T12:00:00Z").getUTCDay();
const at = (key: string, minutes: number) =>
  new Date(
    Date.parse(`${key}T00:00:00${TZ_OFFSET}`) + minutes * 60000,
  ).toISOString();

type Request = {
  at: string;
  customer: string | null;
  items: [string, number][];
  /** cash paid in paise; undefined = pays in full */
  paid?: number;
};
type Payment = { at: string; customer: string; amount: number | "all" };

/** Demand that walk-in customers generate. [name, weight, qty choices] */
const WALK_IN: [string, number, number[]][] = [
  ["Sugar", 5, [500, 1000, 1000, 2000]],
  ["Rice", 4, [1000, 2000, 5000]],
  ["Atta", 4, [1000, 2000, 5000]],
  ["Toor Dal", 3, [500, 1000]],
  ["Mustard Oil", 2, [1000]],
  ["Tea", 2, [1000]],
  ["Milk", 6, [1000, 2000]],
  ["Biscuits", 5, [1000, 2000, 3000]],
  ["Salt", 2, [1000]],
  ["Eggs", 3, [6000, 12000]],
  ["Soap", 2, [1000, 2000]],
  ["Noodles", 4, [1000, 2000, 4000]],
];
const LEFT_LOW = ["Tea", "Toor Dal", "Mustard Oil"];
const BILLS_PER_WEEKDAY = [12, 7, 8, 7, 7, 8, 11]; // Sun..Sat

export function demoTimeline(now = Date.now()) {
  const today = istDay(now);
  // Most recent *completed* Tuesday.
  let dip = addDays(today, -1);
  while (weekday(dip) !== 2) dip = addDays(dip, -1);
  const requests: Request[] = [];
  const payments: Payment[] = [];
  for (let offset = HISTORY_DAYS; offset >= 0; offset--) {
    const day = addDays(today, -offset);
    const wd = weekday(day);
    const r = rng(offset * 7919 + 17);
    const pick = () => {
      const total = WALK_IN.reduce((n, w) => n + w[1], 0);
      let x = r() * total;
      for (const w of WALK_IN) if ((x -= w[1]) < 0) return w;
      return WALK_IN[0];
    };
    for (let b = 0; b < BILLS_PER_WEEKDAY[wd]; b++) {
      const lines = new Map<string, number>();
      const count = 1 + Math.floor(r() * 3);
      for (let i = 0; i < count; i++) {
        const [name, , choices] = pick();
        lines.set(name, choices[Math.floor(r() * choices.length)]);
      }
      requests.push({
        at: at(day, 8 * 60 + Math.floor(((b + r()) / BILLS_PER_WEEKDAY[wd]) * 13 * 60)),
        customer: null,
        items: [...lines],
      });
    }
    // Ramesh: tea stall, Tuesday & Friday morning, all on credit; pays Sundays.
    if ((wd === 2 || wd === 5) && day !== dip)
      requests.push({
        at: at(day, 10 * 60 + 35),
        customer: "Ramesh",
        items: [["Milk", 20000], ["Sugar", 5000], ["Tea", 3000], ["Biscuits", 12000]],
        paid: 0,
      });
    if (wd === 0) payments.push({ at: at(day, 18 * 60 + 10), customer: "Ramesh", amount: "all" });
    // Meena: Mon/Thu/Sat, pays ₹200 at the counter, settles on Saturday evening.
    if (wd === 1 || wd === 4 || wd === 6)
      requests.push({
        at: at(day, 11 * 60 + 5),
        customer: "Meena",
        items: [["Rice", 5000], ["Toor Dal", 1000], ["Milk", 2000], ["Soap", 1000]],
        paid: 20000,
      });
    if (wd === 6) payments.push({ at: at(day, 18 * 60 + 40), customer: "Meena", amount: "all" });
    // Suresh: Wed/Sun, pays cash.
    if (wd === 3 || wd === 0)
      requests.push({
        at: at(day, 9 * 60 + 10),
        customer: "Suresh",
        items: [["Eggs", 12000], ["Noodles", 4000], ["Milk", 2000]],
      });
    // Anita: big Sunday shop, pays cash.
    if (wd === 0)
      requests.push({
        at: at(day, 17 * 60 + 20),
        customer: "Anita",
        items: [["Atta", 5000], ["Rice", 5000], ["Mustard Oil", 1000], ["Sugar", 2000], ["Salt", 1000]],
      });
    // Farooq: every third day on credit; paid once early on, never since.
    if (offset % 3 === 0 && offset <= 32)
      requests.push({
        at: at(day, 19 * 60 + 15),
        customer: "Farooq",
        items: [["Atta", 5000], ["Mustard Oil", 1000], ["Toor Dal", 1000]],
        paid: 0,
      });
    if (offset === 26) payments.push({ at: at(day, 19 * 60 + 30), customer: "Farooq", amount: 50000 });
    // Lakshmi: one credit purchase three-odd weeks ago, nothing since.
    if (offset === 24)
      requests.push({
        at: at(day, 16 * 60),
        customer: "Lakshmi",
        items: [["Rice", 5000], ["Sugar", 1000], ["Tea", 1000]],
        paid: 0,
      });
    // The last Ghee sale was more than a month ago.
    if (offset === HISTORY_DAYS - 1)
      requests.push({ at: at(day, 12 * 60), customer: null, items: [["Ghee", 1000]] });
    // A guaranteed sugar buyer just before 1 pm on the dip Tuesday.
    if (day === dip)
      requests.push({ at: at(day, 11 * 60 + 20), customer: null, items: [["Sugar", 2000], ["Milk", 1000]] });
  }
  const cutoff = new Date(now - 10 * 60000).toISOString();
  return {
    today,
    dip,
    requests: requests.filter((q) => q.at <= cutoff).sort((a, b) => a.at.localeCompare(b.at)),
    payments: payments.filter((p) => p.at <= cutoff),
  };
}

export function seedDemo(ledger: Ledger, token: string, now = Date.now()) {
  if (ledger.state(token).version)
    throw Error("Seed requires empty isolated shop");
  const commit = (kind: string, data: any) =>
    ledger.confirm(token, ledger.preview(token, kind, data).id);
  commit("configure_shop", {
    name: "Sharma General Store (demo)",
    currency: "INR",
    timezone: "Asia/Kolkata",
  });
  const ids = new Map<string, string>();
  for (const p of DEMO_PRODUCTS) ids.set(p.name, commit("add_item", p).id);
  for (const c of DEMO_CUSTOMERS) commit("add_customer", { name: c, balance: 0 });

  const { requests, payments, dip, today } = demoTimeline(now);
  const product = new Map(DEMO_PRODUCTS.map((p) => [p.name, p]));
  const stock = new Map(DEMO_PRODUCTS.map((p) => [p.name, p.stock]));
  const balance = new Map(DEMO_CUSTOMERS.map((c) => [c, 0]));
  // Average daily demand per item, to size deliveries like a real shopkeeper.
  const firstDay = requests[0]?.at.slice(0, 10);
  const days = Math.max(1, (now - Date.parse(firstDay ?? new Date(now).toISOString())) / 86400000);
  const demand = new Map<string, number>();
  for (const q of requests)
    for (const [n, qty] of q.items) demand.set(n, (demand.get(n) ?? 0) + qty / days);

  type Op = { at: string; order: number; run: () => void };
  const ops: Op[] = [];
  for (const q of requests)
    ops.push({
      at: q.at,
      order: 1,
      run: () => {
        const lines = q.items
          .map(([name, want]) => {
            const have = stock.get(name)!;
            const p = product.get(name)!;
            let qty = Math.min(want, have);
            if (p.unit !== "kg") qty -= qty % 1000;
            return { name, qty };
          })
          .filter((l) => l.qty > 0);
        if (!lines.length) return;
        const total = lines.reduce((n, l) => n + (product.get(l.name)!.price * l.qty) / 1000, 0);
        const paid = q.paid === undefined || !q.customer ? undefined : Math.min(q.paid, total);
        commit("record_sale", {
          customer: q.customer,
          lines: lines.map((l) => ({ item: ids.get(l.name)!, qty: l.qty })),
          ...(q.customer ? { paid: paid ?? total } : {}),
          effectiveAt: q.at,
        });
        for (const l of lines) stock.set(l.name, stock.get(l.name)! - l.qty);
        if (q.customer) balance.set(q.customer, balance.get(q.customer)! + total - (paid ?? total));
      },
    });
  for (const p of payments)
    ops.push({
      at: p.at,
      order: 2,
      run: () => {
        const owed = balance.get(p.customer)!;
        const amount = p.amount === "all" ? owed : Math.min(p.amount, owed);
        if (amount <= 0) return;
        commit("record_payment", { customer: p.customer, amount, effectiveAt: p.at });
        balance.set(p.customer, owed - amount);
      },
    });
  // Morning deliveries (8 am) for every day in the history.
  const dayKeys = [...new Set(requests.map((q) => istDay(Date.parse(q.at))))];
  // The sugar supplier delivers short six days before the dip and then skips.
  const shortDay = addDays(dip, -6);
  const cutoff = new Date(now - 10 * 60000).toISOString();
  for (const key of dayKeys.filter((k) => at(k, 8 * 60 - 30) <= cutoff))
    ops.push({
      at: at(key, 8 * 60 - 30),
      order: 0,
      run: () => {
        const lines: { item: string; qty: number; price: number }[] = [];
        for (const p of DEMO_PRODUCTS) {
          if (p.name === "Ghee" || p.name === "Hair Oil") continue;
          const perDay = demand.get(p.name) ?? 0;
          const have = stock.get(p.name)!;
          let qty = 0;
          if (p.name === "Sugar" && key > shortDay && key <= dip) continue; // supplier missed
          // A few items are left running low going into today (but not out).
          const lowRun = LEFT_LOW.includes(p.name) && key >= addDays(today, -3);
          if (p.name === "Sugar" && key === shortDay) {
            // Short delivery: enough only until late morning on the dip Tuesday.
            const until = at(dip, 11 * 60 + 30);
            const need = requests
              .filter((q) => q.at >= at(key, 0) && q.at < until)
              .reduce((n, q) => n + (q.items.find(([x]) => x === "Sugar")?.[1] ?? 0), 0);
            qty = Math.max(0, need - have);
          } else if (have < perDay * (lowRun ? 0.6 : 2)) {
            const target = perDay * (lowRun ? 1.4 : p.name === "Sugar" ? 4 : 6);
            qty = Math.ceil((target - have) / p.pack) * p.pack;
          }
          if (p.unit !== "kg") qty = Math.ceil(qty / 1000) * 1000;
          if (qty > 0) {
            lines.push({ item: ids.get(p.name)!, qty, price: p.cost });
            stock.set(p.name, have + qty);
          }
        }
        if (lines.length)
          commit("record_purchase", { lines, effectiveAt: at(key, 8 * 60 - 30) });
      },
    });
  // Deliveries, sales and payments in time order.
  ops.sort((a, b) => a.at.localeCompare(b.at) || a.order - b.order);
  for (const op of ops) op.run();
  return ledger.state(token);
}
